-- Colleges (tenants).
-- Tables: College
-- Generated by server/scripts/export-sql.mjs from the migrated database. Run the files in numeric order on an empty database.

BEGIN;

CREATE TABLE public."College" (
    id text NOT NULL,
    name text NOT NULL,
    slug text NOT NULL,
    active boolean DEFAULT true NOT NULL,
    i_ts timestamp(3) without time zone DEFAULT CURRENT_TIMESTAMP CONSTRAINT "College_createdAt_not_null" NOT NULL,
    u_ts timestamp(3) without time zone,
    crte_usr_id text,
    updte_usr_id text,
    a_in smallint DEFAULT 1 NOT NULL,
    d_ts timestamp(3) without time zone,
    CONSTRAINT "College_a_in_check" CHECK ((a_in = ANY (ARRAY[0, 1])))
);

ALTER TABLE ONLY public."College"
    ADD CONSTRAINT "College_pkey" PRIMARY KEY (id);

CREATE UNIQUE INDEX "College_slug_key" ON public."College" USING btree (slug);

CREATE TRIGGER "College_audit_timestamps" BEFORE UPDATE ON public."College" FOR EACH ROW EXECUTE FUNCTION public.campus_set_audit_timestamps();

COMMIT;
